# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM\'DA MÜLKİYET ANLAYIŞI VE MALIN KORUNMASI (HIFZU\'L-MÂL)</text>\n  <rect x="20" y="44" width="210" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">1. Mutlak ve Emanet Mülkiyet</text>\n  <rect x="34" y="78" width="182" height="30" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="125" y="97" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Mâlikü\'l-Mülk: Yüce Allah</text>\n  <text x="32" y="126" font-size="10" fill="#334155">• Göklerin ve yerin gerçek ve</text>\n  <text x="40" y="141" font-size="10" fill="#334155">mutlak sahibi Yüce Allah\'tır.</text>\n  <text x="32" y="165" font-size="10" fill="#334155">• İnsan mal üzerinde <tspan font-weight="bold">emanetçi</tspan></text>\n  <text x="40" y="180" font-size="10" fill="#334155">konumundadır; ahirette</text>\n  <text x="40" y="195" font-size="10" fill="#334155">"nereden kazanıp nereye</text>\n  <text x="40" y="210" font-size="10" fill="#334155">harcadığından" sorgulanacaktır.</text>\n\n  <rect x="245" y="44" width="210" height="194" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">2. Özel Mülkiyet ve Hıfzu\'l-Mâl</text>\n  <rect x="259" y="78" width="182" height="30" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="97" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Zarûrât-ı Diniyye (5 Temel Esas)</text>\n  <text x="257" y="126" font-size="10" fill="#334155">• Helal yolla kazanılan özel</text>\n  <text x="265" y="141" font-size="10" fill="#334155">mülkiyet hakkı dokunulmazdır.</text>\n  <text x="257" y="165" font-size="10" fill="#334155">• Hırsızlık, gasp, dolandırıcılık</text>\n  <text x="265" y="180" font-size="10" fill="#334155">ve talan kesin olarak haramdır.</text>\n  <text x="257" y="202" font-size="10" font-weight="bold" fill="#1e40af">• Veda Hutbesi İlkesi:</text>\n  <text x="265" y="217" font-size="9.5" fill="#334155">Can ve mal güvenliği mukaddestir.</text>\n\n  <rect x="470" y="44" width="210" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">3. Mülkiyetin Sorumlulukları</text>\n  <rect x="484" y="78" width="182" height="30" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="575" y="97" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">Zekât · İnfak · Kamu Yararı</text>\n  <text x="482" y="126" font-size="10" fill="#334155">• Zekât ve sadaka ile fakirin</text>\n  <text x="490" y="141" font-size="10" fill="#334155">hakkı servetten çıkarılır.</text>\n  <text x="482" y="165" font-size="10" fill="#334155">• İsraf (savurganlık) ve cimrilik</text>\n  <text x="490" y="180" font-size="10" fill="#334155">yerine itidal (denge) gözetilir.</text>\n  <text x="482" y="202" font-size="10" fill="#334155">• Servet yalnız zenginler arasında</text>\n  <text x="490" y="217" font-size="10" fill="#334155">dolaşan bir tekel olamaz (Haşr, 7).</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">EMEK, RIZIK, TEVEKKÜL VE HELAL KAZANÇ İLKELERİ</text>\n  <rect x="20" y="44" width="320" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">1. Rızık, Emek (Sa\'y) ve Tevekkül</text>\n  <rect x="34" y="78" width="292" height="32" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="180" y="98" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">"İnsan için ancak çalıştığının karşılığı vardır" (Necm, 39)</text>\n  <text x="34" y="128" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#92400e">er-Rezzâk:</tspan> Rızkı yaratan Yüce Allah\'tır; kulun</text>\n  <text x="42" y="143" font-size="10" fill="#334155">görevi rızkını helal yoldan aramaktır.</text>\n  <text x="34" y="165" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#92400e">El Emeği:</tspan> En hayırlı kazanç kişinin kendi</text>\n  <text x="42" y="180" font-size="10" fill="#334155">elinin emeği ve alın teriyle kazandığıdır.</text>\n  <text x="34" y="202" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#92400e">Sahih Tevekkül:</tspan> Tembellik değil, çalışıp gayret</text>\n  <text x="42" y="217" font-size="10" fill="#334155">gösterdikten sonra Allah\'a güvenmektir.</text>\n\n  <rect x="360" y="44" width="320" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. İş ve Ticaret Ahlakı İlkeleri</text>\n  <rect x="374" y="78" width="292" height="32" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="98" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">"Doğru ve güvenilir tacir peygamberlerle beraberdir"</text>\n  <text x="374" y="128" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#15803d">İşçi Hakkı:</tspan> Çalışanın ücreti alın teri kurumadan</text>\n  <text x="382" y="143" font-size="10" fill="#334155">tam ve zamanında ödenmelidir.</text>\n  <text x="374" y="165" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#15803d">Liyakat ve İhsan (İtkân):</tspan> Yaptığı işi en sağlam,</text>\n  <text x="382" y="180" font-size="10" fill="#334155">kaliteli ve dürüst biçimde yapmak esastır.</text>\n  <text x="374" y="202" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#15803d">Karşılıklı Rıza:</tspan> Ticaret tarafların özgür iradesi</text>\n  <text x="382" y="217" font-size="10" fill="#334155">ve karşılıklı hoşnutluğu (an-terâdın) ile yapılır.</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM\'DA YASAKLANAN HAKSIZ KAZANÇ YOLLARI (BÂTIL KAZANÇLAR)</text>\n  <rect x="20" y="44" width="660" height="38" rx="8" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">Temel İlke (Nisâ, 29): "Ey iman edenler! Mallarınızı aranızda bâtıl (haksız) yollarla yemeyin..."</text>\n\n  <rect x="20" y="94" width="156" height="144" rx="8" fill="#ffffff" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="98" y="116" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">1. Faiz (Ribâ)</text>\n  <text x="28" y="138" font-size="9.5" fill="#334155">• Emek ve üretim olmadan</text>\n  <text x="34" y="152" font-size="9.5" fill="#334155">paradan haksız fazlalık</text>\n  <text x="34" y="166" font-size="9.5" fill="#334155">elde etmektir.</text>\n  <text x="28" y="188" font-size="9.5" font-weight="bold" fill="#991b1b">• Bakara, 275:</text>\n  <text x="28" y="202" font-size="9.5" fill="#334155">"Allah ticareti helal,</text>\n  <text x="28" y="216" font-size="9.5" fill="#334155">faizi haram kılmıştır."</text>\n\n  <rect x="188" y="94" width="156" height="144" rx="8" fill="#ffffff" stroke="#d97706" stroke-width="1.8"/>\n  <text x="266" y="116" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">2. İhtikâr (Karaborsa)</text>\n  <text x="196" y="138" font-size="9.5" fill="#334155">• Temel ihtiyaç mallarını</text>\n  <text x="202" y="152" font-size="9.5" fill="#334155">stoklayıp kıtlık oluşturarak</text>\n  <text x="202" y="166" font-size="9.5" fill="#334155">fahiş fiyata satmaktır.</text>\n  <text x="196" y="188" font-size="9.5" font-weight="bold" fill="#92400e">• Hadis-i Şerif:</text>\n  <text x="196" y="202" font-size="9.5" fill="#334155">"Karaborsacılık yapan</text>\n  <text x="196" y="216" font-size="9.5" fill="#334155">kimse günahkârdır."</text>\n\n  <rect x="356" y="94" width="156" height="144" rx="8" fill="#ffffff" stroke="#7c3aed" stroke-width="1.8"/>\n  <text x="434" y="116" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#5b21b6">3. Ölçü-Tartıda Hile</text>\n  <text x="364" y="138" font-size="9.5" fill="#334155">• Eksik tartmak ve malın</text>\n  <text x="370" y="152" font-size="9.5" fill="#334155">kusurunu gizleyerek</text>\n  <text x="370" y="166" font-size="9.5" fill="#334155">müşteriyi aldatmaktır.</text>\n  <text x="364" y="188" font-size="9.5" font-weight="bold" fill="#5b21b6">• Mutaffifîn, 1 &amp; Hadis:</text>\n  <text x="364" y="202" font-size="9.5" fill="#334155">"Eksik ölçüp tartanların</text>\n  <text x="364" y="216" font-size="9.5" fill="#334155">vay hâline! / Bizi aldatan..."</text>\n\n  <rect x="524" y="94" width="156" height="144" rx="8" fill="#ffffff" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="602" y="116" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">4. Rüşvet ve Kumar</text>\n  <text x="532" y="138" font-size="9.5" fill="#334155">• <tspan font-weight="bold">Rüşvet:</tspan> Kamu yetkisini</text>\n  <text x="538" y="152" font-size="9.5" fill="#334155">haksız menfaat için</text>\n  <text x="538" y="166" font-size="9.5" fill="#334155">kötüye kullanmaktır.</text>\n  <text x="532" y="186" font-size="9.5" fill="#334155">• <tspan font-weight="bold">Kumar (Meysir):</tspan> Emeksiz</text>\n  <text x="538" y="200" font-size="9.5" fill="#334155">ve şansa dayalı yıkıcı</text>\n  <text x="538" y="214" font-size="9.5" fill="#334155">haksız kazançtır (Mâide, 90).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
